    results.sort((a,b)=>a.sk-b.sk);
    let shown=results.slice(0,5);
    if(shown.length&&shown.every(r=>seen.has(key(r)))){seen.clear();results.forEach(r=>{r.sk=r.valDiff+Math.random()*40;});results.sort((a,b)=>a.sk-b.sk);shown=results.slice(0,5);}
